-- The Forge of Souls: SmartAI for the Soulguard trash and the Spiteful Apparition
-- Ported from TrinityCore 3.3.5. Heroic casts use the normal spell id, whose heroic numbers are in the 5.4.8 client data.

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (36499,36516,36522,36551,36564,36620) AND `AIName` = '' AND `ScriptName` = '';

DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (36499,36516,36522,36551,36564,36620);
